arguments.command:
python3 - <<'EOF'
import json, glob

total = 0
counts = {}
for path in sorted(glob.glob('data/*.jsonl')):
    for line in open(path):
        line = line.strip()
        if not line:
            continue
        rec = json.loads(line)
        kind = rec.get('kind')
        counts[kind] = counts.get(kind, 0) + 1
        if kind != 'span':
            continue
        elapsed = rec.get('body', {}).get('span', {}).get('elapsed')
        if elapsed is None:
            continue
        value, unit = elapsed['value'], elapsed['unit']
        if unit == 'ms':
            total += value
        elif unit == 'us':
            total += value // 1000
        elif unit == 's':
            total += value * 1000
        else:
            raise ValueError(unit)
print('total', total)
print('kinds', counts)
EOF
